import { createStore } from '@xstate/store';
import * as Schema from 'effect/Schema';

import {
  ANALYTICS_EVENTS,
  ANALYTICS_INSIGHT_TABS,
  ANALYTICS_TIMEFRAMES,
} from '@/constants';

const AnalyticsTimeframeSchema = Schema.Literal(
  ANALYTICS_TIMEFRAMES.LAST_WEEK,
  ANALYTICS_TIMEFRAMES.LAST_FOUR_WEEKS,
  ANALYTICS_TIMEFRAMES.ALL_TIME,
);

const initialContext = {
  insightTab: ANALYTICS_INSIGHT_TABS.GUIDING_BELIEF,
  monthOffset: 0,
  patternIndex: 0,
  timeframe: ANALYTICS_TIMEFRAMES.LAST_WEEK,
};

export const createAnalyticsStore = () => createStore({
  schemas: {
    context: Schema.standardSchemaV1(Schema.Struct({
      insightTab: Schema.Literal(
        ANALYTICS_INSIGHT_TABS.GUIDING_BELIEF,
        ANALYTICS_INSIGHT_TABS.PATTERN,
      ),
      monthOffset: Schema.Int,
      patternIndex: Schema.Int,
      timeframe: AnalyticsTimeframeSchema,
    })),
    events: {
      [ANALYTICS_EVENTS.PREVIOUS_MONTH_REQUESTED]: Schema.standardSchemaV1(Schema.Struct({})),
      [ANALYTICS_EVENTS.NEXT_MONTH_REQUESTED]: Schema.standardSchemaV1(Schema.Struct({})),
      [ANALYTICS_EVENTS.CURRENT_MONTH_REQUESTED]: Schema.standardSchemaV1(Schema.Struct({})),
      [ANALYTICS_EVENTS.TIMEFRAME_SELECTED]: Schema.standardSchemaV1(Schema.Struct({
        timeframe: AnalyticsTimeframeSchema,
      })),
      [ANALYTICS_EVENTS.INSIGHT_TAB_SELECTED]: Schema.standardSchemaV1(Schema.Struct({
        tab: Schema.Literal(
          ANALYTICS_INSIGHT_TABS.GUIDING_BELIEF,
          ANALYTICS_INSIGHT_TABS.PATTERN,
        ),
      })),
      [ANALYTICS_EVENTS.NEXT_PATTERN_REQUESTED]: Schema.standardSchemaV1(Schema.Struct({
        patternCount: Schema.Int,
      })),
    },
  },
  context: initialContext,
  on: {
    [ANALYTICS_EVENTS.PREVIOUS_MONTH_REQUESTED]: (context) => ({
      ...context,
      monthOffset: context.monthOffset - 1,
    }),
    [ANALYTICS_EVENTS.NEXT_MONTH_REQUESTED]: (context) => ({
      ...context,
      monthOffset: Math.min(context.monthOffset + 1, 0),
    }),
    [ANALYTICS_EVENTS.CURRENT_MONTH_REQUESTED]: (context) => ({
      ...context,
      monthOffset: 0,
    }),
    [ANALYTICS_EVENTS.TIMEFRAME_SELECTED]: (context, event) => ({
      ...context,
      insightTab: ANALYTICS_INSIGHT_TABS.GUIDING_BELIEF,
      monthOffset: 0,
      patternIndex: 0,
      timeframe: event.timeframe,
    }),
    [ANALYTICS_EVENTS.INSIGHT_TAB_SELECTED]: (context, event) => ({
      ...context,
      insightTab: event.tab,
    }),
    [ANALYTICS_EVENTS.NEXT_PATTERN_REQUESTED]: (context, event) => ({
      ...context,
      patternIndex: event.patternCount > 1
        ? (context.patternIndex + 1) % event.patternCount
        : 0,
    }),
  },
});
import { fbs } from 'fbtee';
import assert from '@/assert';

import { ANALYTICS_TIMEFRAMES, APP_LOCALES } from '@/constants';
import type { BeliefStatement } from '@/features/beliefs/domain/belief-statement';
import type { AppLocale } from '@/localization/app-locale';
import type { AnalyticsObservation } from '../domain/check-in-analytics';
import type {
  AnalyticsDateRange,
  AnalyticsTimeframe,
  TopLeitsatz,
} from '../domain/analytics-timeframe';
import type { CalendarEmotionFrequency } from '../domain/analytics-calendar';
import { beliefSystemText } from '@/features/beliefs/ui/belief-system-copy';
import { emotionName } from '@/features/check-in/ui/emotion-copy';

const englishCalendarDateFormatter = new Intl.DateTimeFormat(APP_LOCALES.ENGLISH, {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});
const germanCalendarDateFormatter = new Intl.DateTimeFormat(APP_LOCALES.GERMAN, {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});
const englishMonthFormatter = new Intl.DateTimeFormat(APP_LOCALES.ENGLISH, {
  month: 'long',
  year: 'numeric',
});
const germanMonthFormatter = new Intl.DateTimeFormat(APP_LOCALES.GERMAN, {
  month: 'long',
  year: 'numeric',
});
const englishWeekdayFormatter = new Intl.DateTimeFormat(APP_LOCALES.ENGLISH, {
  weekday: 'narrow',
});
const germanWeekdayFormatter = new Intl.DateTimeFormat(APP_LOCALES.GERMAN, {
  weekday: 'narrow',
});
const englishRangeDateFormatter = new Intl.DateTimeFormat(APP_LOCALES.ENGLISH, {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
});
const germanRangeDateFormatter = new Intl.DateTimeFormat(APP_LOCALES.GERMAN, {
  day: 'numeric',
  month: 'short',
  year: 'numeric',
});

function localeFormatter({
  english,
  german,
  locale,
}: {
  english: Intl.DateTimeFormat;
  german: Intl.DateTimeFormat;
  locale: AppLocale;
}) {
  return locale === APP_LOCALES.GERMAN ? german : english;
}

export function analyticsMonthLabel({ date, locale }: { date: Date; locale: AppLocale }) {
  return localeFormatter({
    english: englishMonthFormatter,
    german: germanMonthFormatter,
    locale,
  }).format(date);
}

export function analyticsWeekdayLabel({ date, locale }: { date: Date; locale: AppLocale }) {
  return localeFormatter({
    english: englishWeekdayFormatter,
    german: germanWeekdayFormatter,
    locale,
  }).format(date);
}

function analyticsDateRangeLabel({
  end,
  locale,
  start,
}: {
  end: Date;
  locale: AppLocale;
  start: Date;
}) {
  const formatter = localeFormatter({
    english: englishRangeDateFormatter,
    german: germanRangeDateFormatter,
    locale,
  });
  return `${formatter.format(start)} – ${formatter.format(end)}`;
}

export function analyticsTimeframeRangeLabel({
  locale,
  range,
  timeframe,
}: {
  locale: AppLocale;
  range: AnalyticsDateRange;
  timeframe: AnalyticsTimeframe;
}) {
  assert(Object.values(ANALYTICS_TIMEFRAMES).includes(timeframe), 'Analytics timeframe must be supported.');
  assert(range.end.getTime() >= (range.start?.getTime() ?? range.end.getTime()), 'Analytics range cannot end before it starts.');
  if (timeframe === ANALYTICS_TIMEFRAMES.ALL_TIME || range.start === null) {
    return String(fbs('All recorded moments', 'Date range label for all-time analytics'));
  }
  const inclusiveEnd = new Date(
    range.end.getFullYear(),
    range.end.getMonth(),
    range.end.getDate() - 1,
  );
  return analyticsDateRangeLabel({ end: inclusiveEnd, locale, start: range.start });
}

export function topLeitsatzEvidenceCopy({
  leitsatz,
  locale,
  range,
  timeframe,
}: {
  leitsatz: TopLeitsatz;
  locale: AppLocale;
  range: AnalyticsDateRange;
  timeframe: AnalyticsTimeframe;
}) {
  assert(leitsatz.count > 0, 'Top guiding-belief evidence requires a positive count.');
  assert(leitsatz.supportingIds.length >= leitsatz.count, 'Guiding-belief evidence must support its displayed count.');
  const rangeLabel = analyticsTimeframeRangeLabel({ locale, range, timeframe });
  return String(fbs(
    'Selected '
      + fbs.param('count', String(leitsatz.count))
      + ' times · '
      + fbs.param('range', rangeLabel),
    'Evidence below the most frequently selected guiding belief in the selected analytics timeframe',
  ));
}

export function topLeitsatzLabel({
  multiple,
  timeframe,
}: {
  multiple: boolean;
  timeframe: AnalyticsTimeframe;
}) {
  assert(Object.values(ANALYTICS_TIMEFRAMES).includes(timeframe), 'Guiding-belief label timeframe must be supported.');
  const label = timeframe === ANALYTICS_TIMEFRAMES.LAST_WEEK
    ? multiple
      ? String(fbs(
        "LAST WEEK'S GUIDING BELIEFS",
        'Label for equally most frequently selected positive guiding statements last week',
      ))
      : String(fbs(
        "LAST WEEK'S GUIDING BELIEF",
        'Label for the most frequently selected positive guiding statement last week',
      ))
    : timeframe === ANALYTICS_TIMEFRAMES.LAST_FOUR_WEEKS
      ? multiple
      ? String(fbs(
        "LAST 4 WEEKS' GUIDING BELIEFS",
        'Label for equally most frequently selected positive guiding statements in the last four weeks',
      ))
      : String(fbs(
        "LAST 4 WEEKS' GUIDING BELIEF",
        'Label for the most frequently selected positive guiding statement in the last four weeks',
      ))
      : multiple
        ? String(fbs(
          'ALL-TIME GUIDING BELIEFS',
          'Label for equally most frequently selected positive guiding statements across all recorded moments',
        ))
        : String(fbs(
          'ALL-TIME GUIDING BELIEF',
          'Label for the most frequently selected positive guiding statement across all recorded moments',
        ));
  assert(label.length > 0, 'Guiding-belief label cannot be empty.');
  return label;
}

export function additionalTopLeitsaetzeCopy(count: number) {
  return String(fbs(
    fbs.param('count', String(count)) + ' more were selected equally often.',
    'Copy below tied guiding beliefs when more equally frequent beliefs exist than the card displays',
  ));
}

export function observationCopy({ observation, statements }: {
  observation: AnalyticsObservation;
  statements: readonly BeliefStatement[];
}) {
  assert(observation.kind === 'history' ? observation.momentCount > 0 : observation.count > 0, 'Analytics observation requires positive evidence.');
  assert(observation.kind !== 'history' || observation.dayCount <= observation.momentCount, 'History observation cannot have more days than moments.');
  if (observation.kind === 'history') {
    return String(fbs(
      'You recorded '
        + fbs.param('momentCount', String(observation.momentCount))
        + ' moments across '
        + fbs.param('dayCount', String(observation.dayCount))
        + ' different days.',
      'Analytics observation summarizing recorded moments and days',
    ));
  }
  if (observation.kind === 'emotion') {
    return String(fbs(
      fbs.param('emotion', emotionName(observation.emotionId))
        + ' appeared in '
        + fbs.param('count', String(observation.count))
        + ' of the moments you chose to record.',
      'Analytics observation about the most frequently recorded emotion',
    ));
  }
  if (observation.kind === 'belief') {
    const belief = beliefSystemText({
      id: observation.beliefSystemId,
      statements,
    }).replace(/[.!?]+$/u, '');
    return String(fbs(
      fbs.param('belief', `“${belief}”`)
        + ' appeared alongside '
        + fbs.param('emotion', emotionName(observation.emotionId))
        + ' in '
        + fbs.param('count', String(observation.count))
        + ' recorded moments.',
      'Analytics observation about a recurring emotion and core belief pairing',
    ));
  }
  return String(fbs(
    'You added a written reflection to '
      + fbs.param('count', String(observation.count))
      + ' of '
      + fbs.param('momentCount', String(observation.momentCount))
      + ' recorded moments.',
    'Analytics observation summarizing written reflection use',
  ));
}

export function insightEvidenceCopy({
  momentCount,
  rangeLabel,
  supportingCount,
}: {
  momentCount: number;
  rangeLabel: string;
  supportingCount: number;
}) {
  return String(fbs(
    'Based on '
      + fbs.param('supportingCount', String(supportingCount))
      + ' of '
      + fbs.param('momentCount', String(momentCount))
      + ' moments · '
      + fbs.param('range', rangeLabel),
    'Evidence count and comparison period below the primary analytics insight',
  ));
}

export function insightLearningCopy(remainingCount: number) {
  return String(fbs(
    'Record '
      + fbs.param('remainingCount', String(remainingCount))
      + ' more moments in this period to reveal a pattern with visible evidence.',
    'Analytics learning state before enough moments exist for an insight',
  ));
}

export function insightNoPatternCopy({ momentCount, rangeLabel }: {
  momentCount: number;
  rangeLabel: string;
}) {
  return String(fbs(
    'No single recurring pattern stands out across '
      + fbs.param('momentCount', String(momentCount))
      + ' moments · '
      + fbs.param('range', rangeLabel)
      + '. That is useful to know too.',
    'Honest analytics state when enough data exists but no unique pattern stands out',
  ));
}

export function calendarDayAccessibilityLabel({
  date,
  frequencies,
  locale,
}: {
  date: Date;
  frequencies: readonly CalendarEmotionFrequency[];
  locale: AppLocale;
}) {
  assert(Number.isFinite(date.getTime()), 'Calendar accessibility requires a valid date.');
  assert(frequencies.every(({ count }) => count > 0), 'Calendar emotion frequencies must be positive.');
  const dateLabel = localeFormatter({
    english: englishCalendarDateFormatter,
    german: germanCalendarDateFormatter,
    locale,
  }).format(date);
  if (frequencies.length === 0) {
    return String(fbs(
      fbs.param('date', dateLabel) + '. No recorded moments.',
      'Accessibility label for an empty analytics calendar day',
    ));
  }
  const momentCount = frequencies.reduce((total, frequency) => total + frequency.count, 0);
  return String(fbs(
    fbs.param('date', dateLabel)
      + '. '
      + fbs.param('count', String(momentCount))
      + ' recorded moments: '
      + fbs.param('emotions', frequencies.map(({ count, emotionId }) => (
        `${emotionName(emotionId)} ${count}`
      )).join(', '))
      + '.',
    'Accessibility label for an analytics calendar day with ranked emotion counts',
  ));
}
import * as Schema from 'effect/Schema';
import assert from '@/assert';

import { ANALYTICS_TIMEFRAMES } from '@/constants';
import type { CheckIn } from '@/features/check-in/domain/check-in';
import { CheckInIdListSchema } from '@/features/check-in/domain/check-in';
import {
  BeliefStatementText,
  BeliefSystemId,
  beliefStatementForId,
  type BeliefStatement,
} from '@/features/beliefs/domain/belief-statement';

export type AnalyticsTimeframe = typeof AnalyticsTimeframeSchema.Type;
export type TopLeitsatz = typeof TopLeitsatzSchema.Type;
export type TopLeitsatzGroup = Readonly<{
  additionalCount: number;
  leitsaetze: ReadonlyArray<TopLeitsatz>;
  range: AnalyticsDateRange;
  timeframe: AnalyticsTimeframe;
}>;

export type AnalyticsDateRange = Readonly<{ start: Date | null; end: Date }>;
type LeitsatzFrequency = Readonly<{
  beliefSystemId: BeliefSystemId;
  count: number;
  guidingStatement: string;
  latestAt: number;
  supportingIds: ReadonlyArray<CheckIn['id']>;
}>;

export const AnalyticsTimeframeSchema = Schema.Literal(
  ANALYTICS_TIMEFRAMES.LAST_WEEK,
  ANALYTICS_TIMEFRAMES.LAST_FOUR_WEEKS,
  ANALYTICS_TIMEFRAMES.ALL_TIME,
);

export const TopLeitsatzSchema = Schema.Struct({
  beliefSystemId: BeliefSystemId,
  guidingStatement: BeliefStatementText,
  count: Schema.Int.pipe(Schema.positive()),
  supportingIds: CheckInIdListSchema,
});

export function analyticsDateRange({
  now,
  timeframe,
}: {
  now: Date;
  timeframe: AnalyticsTimeframe;
}): AnalyticsDateRange {
  assert(Number.isFinite(now.getTime()), 'Analytics reference date must be valid');
  assert(
    Object.values(ANALYTICS_TIMEFRAMES).includes(timeframe),
    'Analytics timeframe must be supported',
  );
  const end = startOfLocalWeek(now);
  if (timeframe === ANALYTICS_TIMEFRAMES.ALL_TIME) return { start: null, end };
  if (timeframe === ANALYTICS_TIMEFRAMES.LAST_FOUR_WEEKS) {
    return { start: daysBefore({ date: end, dayCount: 28 }), end };
  }
  return { start: daysBefore({ date: end, dayCount: 7 }), end };
}

export function entriesForAnalyticsTimeframe({
  entries,
  now,
  timeframe,
}: {
  entries: readonly CheckIn[];
  now: Date;
  timeframe: AnalyticsTimeframe;
}) {
  assert(Number.isFinite(now.getTime()), 'Analytics reference date must be valid');
  assert(
    Object.values(ANALYTICS_TIMEFRAMES).includes(timeframe),
    'Analytics timeframe must be supported',
  );
  const range = analyticsDateRange({ now, timeframe });
  if (range.start === null) return entries;
  const start = range.start;
  return entries.filter((entry) => {
    const occurredAt = new Date(entry.occurredAt);
    return !Number.isNaN(occurredAt.getTime()) && occurredAt >= start && occurredAt < range.end;
  });
}

export function topLeitsaetzeForTimeframe({
  entries,
  now,
  statements,
  timeframe,
}: {
  entries: readonly CheckIn[];
  now: Date;
  statements: readonly BeliefStatement[];
  timeframe: AnalyticsTimeframe;
}): TopLeitsatzGroup | null {
  assert(Number.isFinite(now.getTime()), 'Analytics reference date must be valid');
  assert(
    Object.values(ANALYTICS_TIMEFRAMES).includes(timeframe),
    'Analytics timeframe must be supported',
  );
  const range = analyticsDateRange({ now, timeframe });
  const timeframeEntries = entriesForAnalyticsTimeframe({
    entries,
    now,
    timeframe,
  });
  const frequencies = timeframeEntries.reduce<readonly LeitsatzFrequency[]>((items, entry) => {
    assert(items.every((item) => item.count > 0), 'Leitsatz frequencies must stay positive');
    assert(items.length <= timeframeEntries.length, 'Frequency groups cannot exceed entries');
    if (!entry.beliefSystemId) return items;
    const statement = beliefStatementForId({
      beliefSystemId: entry.beliefSystemId,
      statements,
    });
    const guidingStatement = entry.guidingStatementSnapshot ?? statement?.guidingStatement;
    if (!guidingStatement) return items;
    const occurredAt = new Date(entry.occurredAt).getTime();
    const existing = items.find(({ beliefSystemId }) => beliefSystemId === entry.beliefSystemId);
    if (!existing) {
      return items.concat({
        beliefSystemId: entry.beliefSystemId,
        count: 1,
        guidingStatement,
        latestAt: occurredAt,
        supportingIds: [entry.id],
      });
    }
    return items.map((item) => item !== existing ? item : {
      ...item,
      count: item.count + 1,
      guidingStatement: occurredAt > item.latestAt ? guidingStatement : item.guidingStatement,
      latestAt: Math.max(occurredAt, item.latestAt),
      supportingIds: item.supportingIds.concat(entry.id),
    });
  }, []);
  const ranked = rankLeitsatzFrequencies(frequencies);
  const highestCount = ranked[0]?.count;
  if (highestCount === undefined) return null;
  const coLeaders = ranked.filter(({ count }) => count === highestCount);
  const visibleLeitsaetze = coLeaders
    .slice(0, MAX_VISIBLE_TOP_LEITSAETZE)
    .map((leader) => TopLeitsatzSchema.make({
      beliefSystemId: leader.beliefSystemId,
      guidingStatement: leader.guidingStatement,
      count: leader.count,
      supportingIds: leader.supportingIds,
    }));
  return {
    additionalCount: coLeaders.length - visibleLeitsaetze.length,
    leitsaetze: visibleLeitsaetze,
    range,
    timeframe,
  };
}

const MAX_VISIBLE_TOP_LEITSAETZE = 3;

const startOfLocalWeek = (date: Date) => {
  const mondayOffset = (date.getDay() + 6) % 7;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() - mondayOffset);
};

const daysBefore = ({ date, dayCount }: { date: Date; dayCount: number }) => {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() - dayCount);
};

const rankLeitsatzFrequencies = (items: readonly LeitsatzFrequency[]) => {
  return items.reduce<readonly LeitsatzFrequency[]>((ranked, item) => {
    assert(item.count > 0, 'Leitsatz frequency must be positive');
    assert(
      ranked.every((frequency) => frequency.count > 0),
      'Ranked Leitsatz frequencies must be positive',
    );
    const insertionIndex = ranked.findIndex((candidate) => (
      item.count > candidate.count
      || (item.count === candidate.count && item.latestAt > candidate.latestAt)
    ));
    if (insertionIndex === -1) return ranked.concat(item);
    return ranked
      .slice(0, insertionIndex)
      .concat(item, ranked.slice(insertionIndex));
  }, []);
};
